"""1452 (#11 emily_far_reach_pull_variants): Probe-ObjectCarry-v1451.ps1 with the Far Reach object pull dumped. 1450a cast
Far Reach (both pull upgrades granted) at the bottle from inside its room: the cast state UsePower 63 latched onto the
bottle, then a new state 84 ran for about 1 s while an object (the source film shows a whiskey tumbler) flew to Emily and
shattered; the bottle stayed. Corvo's window presented Emily's aim, tendril and pull-back, but the pulled object moved only
in the client's world. To sync the pulled target (as 1214ea syncs a held one), 'farreachbottle' now dumps the state
objects of 63 and 84 while they run (twice each; vtable, words) and records which entities within 6 m of the bottle
moved or vanished in the source's world and in the observer's. Generated by make_object_carry_v1452.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Probe-ObjectCarry-v1451.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
first = s.index('\n') + 1
s = s[:first] + "# 1452 (#11): 'farreachbottle' dumps the pull states 63/84 and the moved entities in both worlds. Generated by make_object_carry_v1452.py.\n" + s[first:]
rep("   $target=@((Q $source '--entities').entities|Where-Object name -eq $case.entity);",
    "   $nearSnap={param($r,$c)@((Q $r '--entities').entities|Where-Object {$_.position-and[Math]::Abs($_.position[0]-$c[0])-lt6-and[Math]::Abs($_.position[1]-$c[1])-lt6-and[Math]::Abs($_.position[2]-$c[2])-lt4})}\n"
    "   $target=@((Q $source '--entities').entities|Where-Object name -eq $case.entity);if($case.name-eq'farreachbottle'-and$target.Count){$near0=@{};foreach($q in 'host','client'){$near0[$q]=& $nearSnap $q $target[0].position};Save \"$out/$key-near-before.json\" $near0}\n"
    "   ")
rep("    $player=try{Q $source '--player-states'}catch{$null};",
    "    if($case.name-eq'farreachbottle'-and$holdDumps.Count-lt4){$ps0=try{Q $source '--player-states'}catch{$null}\n"
    "     foreach($sa in @($ps0.active|Where-Object {$_.id-in63,84})){if(@($holdDumps|Where-Object {$_.id-eq$sa.id}).Count-ge2){continue}\n"
    "      $slotAt='0x{0:x}' -f ([Convert]::ToUInt64(($ps0.mode-replace'^0x',''),16)+0x10+$sa.id*8);$statePtr=try{(Q $source '--object' $slotAt).words[0].word}catch{$null};$dump=if($statePtr){try{Q $source '--object' $statePtr}catch{$null}}else{$null}\n"
    "      $holdDumps.Add([pscustomobject]@{ms=$watch.ElapsedMilliseconds;id=$sa.id;vtable=$sa.vtable;slot=$slotAt;state=$statePtr;type=$dump.type;words=$dump.words})}}\n"
    "    $player=try{Q $source '--player-states'}catch{$null};")
rep("    $row.bottleAfter=$(if($moved.Count){$moved[0].position}else{$null});$row.bottleBefore=$target[0].position\n",
    "    $row.bottleAfter=$(if($moved.Count){$moved[0].position}else{$null});$row.bottleBefore=$target[0].position\n"
    "    $row.stateVtables=@($holdDumps|ForEach-Object {'{0}@{1}' -f $_.id,$_.vtable}|Select-Object -Unique);$row.movers=[ordered]@{}\n"
    "    foreach($q in 'host','client'){$after=& $nearSnap $q $target[0].position;$m=@();foreach($e in $near0[$q]){$a=@($after|Where-Object name -eq $e.name)\n"
    "      if(!$a.Count){$m+=[pscustomobject]@{name=$e.name;handle=$e.handle;change='gone'}}else{$d=[Math]::Sqrt([Math]::Pow($a[0].position[0]-$e.position[0],2)+[Math]::Pow($a[0].position[1]-$e.position[1],2)+[Math]::Pow($a[0].position[2]-$e.position[2],2));if($d-gt.02){$m+=[pscustomobject]@{name=$e.name;handle=$e.handle;change=[Math]::Round($d,3);to=$a[0].position}}}}\n"
    "      $row.movers[$q]=$m};Save \"$out/$key-movers.json\" $row.movers\n"
    "    $row.checks.Add(\"Pull states $($row.stateVtables-join ', '); moved in host $(@($row.movers.host|ForEach-Object {\"$($_.name):$($_.change)\"})-join ' '); moved in client $(@($row.movers.client|ForEach-Object {\"$($_.name):$($_.change)\"})-join ' ')\")\n")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Probe-ObjectCarry-v1452.ps1').write_bytes(out.encode('utf-8'))
print('ok')
